(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_tourism_industry','tourism industry','noun','all the businesses and services that provide for people who travel for holidays, such as airlines, tour companies and restaurants','[{"senseId":"tourism_industry_1","meaning":"all the businesses and services that provide for people who travel for holidays, such as airlines, tour companies and restaurants","acceptedParaphrases":["businesses that serve holidaymakers","the business of looking after holidaymakers"],"masteryContexts":[{"contextId":"u5_31_tourism_industry_meaning","text":"Cheap flights and online booking helped the tourism industry to recover quickly after the storm.","meaning":"all the businesses and services that provide for people on holiday","wrongMeanings":["the factories and workshops that make goods for local people","the schools and colleges that train students for their careers","the farms and markets that supply food to the whole country"]},{"contextId":"u5_31_tourism_industry_paraphrase","text":"In small island economies the tourism industry is often the biggest source of jobs, and it can disappear almost overnight if visitors stop coming.","meaning":"the businesses and services connected with people who travel for pleasure","wrongMeanings":["the banks and offices that manage money for local companies","the farms and fisheries that provide food for the island","the schools and hospitals that serve the local community"]}],"situationDistractors":["The village baker gets up at four o’clock every morning to make bread for the shop.","Farmers on the plain were waiting for rain to water their wheat fields.","The new factory produces thousands of bicycle frames every week.","The local council has repaired the roads and replaced the street lights in the town centre.","Students in the school choir rehearsed for the winter concert twice a week.","The fishing boats returned with their nets full of sardines."],"gapDistractors":[{"contextId":"u5_31_tourism_industry_gap_1","answer":"tourism industry","wrong":["fishing industry","car industry","film industry"]},{"contextId":"u5_31_tourism_industry_gap_2","answer":"tourism industry","wrong":["steel industry","farming industry","banking industry"]},{"contextId":"u5_31_tourism_industry_gap_3","answer":"tourism industry","wrong":["mining industry","textile industry","publishing industry"]}],"spellingErrors":["tourism industy","turism industry","tourizm industry","tourism indistry","toorism industry","tourism industri"],"masteryPassages":[{"passageId":"u5_31_tourism_industry_passage_1","contextId":"u5_31_tourism_industry_gap_1","text":"The country has warm weather, ancient ruins and miles of empty coastline. As more visitors arrive, the ____ is growing fast and creating jobs for guides, drivers, cooks and hotel staff.","answer":"tourism industry"},{"passageId":"u5_31_tourism_industry_passage_2","contextId":"u5_31_tourism_industry_gap_2","text":"Many people in the mountain valley used to depend on farming. Today most of the families earn their living in the ____, working in ski shops, cafés and guesthouses.","answer":"tourism industry"}],"contextDependentParaphrases":[],"wrongParaphrases":["factories that make goods for export","farms that grow food for local markets","schools that train young people for jobs"],"misleadingDistractors":["the factories that make goods to sell in other countries","the study of old buildings and monuments in a country","the government offices that give passports to travellers"]}]'::jsonb,'[]'::jsonb,'["work in the tourism industry","support the tourism industry","a thriving tourism industry"]'::jsonb,'live'),
('vocab_exploring','exploring','noun','the activity of travelling around a place or looking at it carefully in order to discover more about it','[{"senseId":"exploring_1","meaning":"the activity of travelling around a place or looking at it carefully in order to discover more about it","acceptedParaphrases":["discovering new places","finding out about a place by travelling around it"],"masteryContexts":[{"contextId":"u5_32_exploring_meaning","text":"On the second day, the group left the camp and spent hours exploring the valley and its hidden waterfalls.","meaning":"travelling around a place to find out what it is like","wrongMeanings":["staying in one place to rest and recover from a journey","packing equipment in preparation for a long walk","waiting for a guide to arrive at a meeting point"]},{"contextId":"u5_32_exploring_paraphrase","text":"The brochure promises plenty of time for exploring the ancient ruins at your own pace.","meaning":"walking and looking around a place to discover more about it","wrongMeanings":["taking photographs of famous places for a magazine","buying tickets for places that tourists want to visit","learning the history of a place from a book"]}],"situationDistractors":["The family stayed in their apartment all day and watched films because of the heavy rain.","The ticket inspector walked down the aisle and punched a hole in every ticket.","Customers waited in a long queue to pay for their groceries at the supermarket.","The conference delegates sat in rows and listened to a talk about marketing.","My grandfather read the newspaper and drank coffee on the balcony all morning.","The mechanic replaced the brake pads and washed the car."],"gapDistractors":[{"contextId":"u5_32_exploring_gap_1","answer":"exploring","wrong":["avoiding","cleaning","measuring"]},{"contextId":"u5_32_exploring_gap_2","answer":"exploring","wrong":["guarding","cutting","fencing"]},{"contextId":"u5_32_exploring_gap_3","answer":"exploring","wrong":["leaving","warning","cleaning"]}],"spellingErrors":["explorring","exploreing","explooring","exploaring","eksploring","explorin"],"wordFamilyForms":[{"form":"exploring","partOfSpeech":"noun","example":"Children love exploring the caves behind the waterfall.","pedagogicallyUseful":true},{"form":"explore","partOfSpeech":"verb","example":"Visitors can explore the old fort at their own pace.","pedagogicallyUseful":true},{"form":"explorer","partOfSpeech":"noun","example":"The explorer spent three years mapping the rivers of the rainforest.","pedagogicallyUseful":true},{"form":"exploration","partOfSpeech":"noun","example":"Early exploration of the Arctic was extremely dangerous.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u5_32_exploring_passage_1","contextId":"u5_32_exploring_gap_1","text":"The cave system has more than forty tunnels, and no two are the same. Visitors with torches and helmets can spend a whole day ____ them, finding underground lakes and strange rock shapes.","answer":"exploring"},{"passageId":"u5_32_exploring_passage_2","contextId":"u5_32_exploring_gap_2","text":"There is no timetable on the trekking holiday. Guests are free to wander through the villages, talk to the local people and enjoy ____ the countryside at their own pace.","answer":"exploring"}],"contextDependentParaphrases":[],"wrongParaphrases":["packing bags for a long trip","buying gifts from market stalls","waiting for a late train"],"misleadingDistractors":["the activity of packing bags before a long trip","the activity of buying souvenirs in local markets","the activity of waiting for transport at a station"],"teacherNote":"Topic-specific noun (gerund): the activity of travelling around a place to discover it. Related forms (explore, explorer, exploration) are the word family."}]'::jsonb,'["explore","explorer","exploration"]'::jsonb,'["go exploring","spend time exploring","exploring on foot"]'::jsonb,'live'),
('vocab_observation','observation','noun','the act of watching someone or something carefully in order to learn about it','[{"senseId":"observation_1","meaning":"the act of watching someone or something carefully in order to learn about it","acceptedParaphrases":["careful watching","close and patient watching"],"masteryContexts":[{"contextId":"u5_33_observation_meaning","text":"Whale watchers rely on observation, because the animals stay on the surface for only a few seconds at a time.","meaning":"the act of watching something carefully in order to learn about it","wrongMeanings":["the act of taking photographs of something for a newspaper","the act of counting something to find out how many there are","the act of guarding something from people who might harm it"]},{"contextId":"u5_33_observation_paraphrase","text":"The students’ observation of the village market over three mornings showed which stalls sold most to visitors.","meaning":"the careful watching of people or events to learn something","wrongMeanings":["the careful planning of people or events to avoid problems","the careful selling of things to people who visit events","the careful counting of money paid by people at events"]}],"situationDistractors":["The children played football in the square until it got dark.","Passengers chatted loudly and ate snacks during the bus ride.","The chef added garlic and chilli to the sauce and stirred it slowly.","The band performed on the open stage while the audience danced.","He signed the receipt and put his card back in his wallet.","Heavy luggage was loaded onto the trolley and wheeled to the lift."],"gapDistractors":[{"contextId":"u5_33_observation_gap_1","answer":"observation","wrong":["interviews","experiments","questionnaires"]},{"contextId":"u5_33_observation_gap_2","answer":"observation","wrong":["invention","decoration","punishment"]},{"contextId":"u5_33_observation_gap_3","answer":"observation","wrong":["gardening","cooking","shopping"]}],"spellingErrors":["observasion","obsevation","observaton","obzervation","observatoin","observeation"],"wordFamilyForms":[{"form":"observation","partOfSpeech":"noun","example":"Scientists learned about the birds’ habits through patient observation.","pedagogicallyUseful":true},{"form":"observe","partOfSpeech":"verb","example":"Visitors can observe seals from a wooden platform without disturbing them.","pedagogicallyUseful":true,"altExample":"Walkers are asked to observe the animals from a distance and never to feed them."},{"form":"observer","partOfSpeech":"noun","example":"A trained observer on the boat counts the whales every hour.","pedagogicallyUseful":true,"altExample":"The expedition included an observer from the national park authority."}],"masteryPassages":[{"passageId":"u5_33_observation_passage_1","contextId":"u5_33_observation_gap_1","text":"Biologists camped beside the lake for a month and wrote down everything the birds did. Their conclusions came from patient ____, not from any experiment or machine.","answer":"observation"},{"passageId":"u5_33_observation_passage_2","contextId":"u5_33_observation_gap_2","text":"On the first evening, the guide taught the group how to sit quietly and keep their eyes on the forest edge. She told them that good ____ is a skill, and that the best way to learn it is to practise.","answer":"observation"}],"contextDependentParaphrases":[],"wrongParaphrases":["quick guessing","careless counting","heavy lifting"],"misleadingDistractors":["a written report on the weather in a region","a short talk given to a group of visitors","a form that visitors must complete at a border"]}]'::jsonb,'["observe","observer"]'::jsonb,'["careful observation","close observation","observation skills"]'::jsonb,'live'),
('vocab_relaxation','relaxation','noun','the state of resting and feeling calm, free from worry or stress','[{"senseId":"relaxation_1","meaning":"the state of resting and feeling calm, free from worry or stress","acceptedParaphrases":["rest and freedom from stress","calm time without worry"],"masteryContexts":[{"contextId":"u5_34_relaxation_meaning","text":"After the hiking trip, the guests spent a day of complete relaxation, reading and sleeping in the garden of the farmhouse.","meaning":"the state of resting and feeling calm, without worry","wrongMeanings":["the state of being busy and excited, with many plans","the state of feeling lost and alone in a strange place","the state of being tired and cross after a long journey"]},{"contextId":"u5_34_relaxation_paraphrase","text":"Some travellers prefer adventure, but others choose a holiday that is all about relaxation, with massage, yoga and long, slow meals.","meaning":"rest and freedom from stress or hard work","wrongMeanings":["exercise and activity that keep the body strong","learning and study that prepare people for exams","adventure and risk that make the heart beat faster"]}],"situationDistractors":["The tour leader hurried from room to room, handing out keys and answering twenty questions at once.","The kitchen staff rushed to prepare two hundred meals before the wedding party arrived.","The climbers tied their ropes and checked each other’s equipment before the steep ascent.","The airline staff worked all night to find seats for hundreds of delayed passengers.","The students argued about which route to take and ran out of time to see the museum.","Heavy traffic made the drivers shout and sound their horns in the narrow street."],"gapDistractors":[{"contextId":"u5_34_relaxation_gap_1","answer":"relaxation","wrong":["competition","training","examination"]},{"contextId":"u5_34_relaxation_gap_2","answer":"relaxation","wrong":["construction","repair","navigation"]},{"contextId":"u5_34_relaxation_gap_3","answer":"relaxation","wrong":["punishment","pollution","taxation"]}],"spellingErrors":["relaxasion","relaxtion","relaxatoin","relacsation","relaxashun","rellaxation"],"wordFamilyForms":[{"form":"relaxation","partOfSpeech":"noun","example":"Yoga and walks in the garden provide gentle relaxation after a busy week.","pedagogicallyUseful":true},{"form":"relax","partOfSpeech":"verb","example":"Guests can relax in a hammock or read in the shade.","pedagogicallyUseful":true},{"form":"relaxed","partOfSpeech":"adjective","example":"The staff were friendly and the atmosphere was relaxed.","pedagogicallyUseful":true},{"form":"relaxing","partOfSpeech":"adjective","example":"A boat trip along the quiet river is a relaxing way to spend the afternoon.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u5_34_relaxation_passage_1","contextId":"u5_34_relaxation_gap_1","text":"The island has no nightclubs, no shopping centres and almost no cars. Most visitors come for ____: they swim, read and sleep late until their worries seem far away.","answer":"relaxation"},{"passageId":"u5_34_relaxation_passage_2","contextId":"u5_34_relaxation_gap_2","text":"After months of long hours at the office, Daniel wanted a holiday that was the opposite of his working life. He chose a quiet mountain retreat devoted to ____, with no phones and no meetings.","answer":"relaxation"}],"contextDependentParaphrases":[],"wrongParaphrases":["effort and preparation for exams","noise and excitement at a festival","speed and competition on a track"],"misleadingDistractors":["physical exercise that keeps the body fit","a group activity that needs a lot of energy","a short period of work between two meetings"]}]'::jsonb,'["relax","relaxed","relaxing"]'::jsonb,'["time for relaxation","relaxation techniques","a place for relaxation"]'::jsonb,'live'),
('vocab_adventurous_activities','adventurous activities','noun','exciting things to do that involve challenge and some risk, such as climbing or white-water rafting','[{"senseId":"adventurous_activities_1","meaning":"exciting things to do that involve challenge and some risk, such as climbing or white-water rafting","acceptedParaphrases":["exciting things to do that involve some risk","thrilling outdoor pursuits"],"masteryContexts":[{"contextId":"u5_35_adventurous_activities_meaning","text":"Teenagers on the summer programme can choose between sailing, abseiling and other adventurous activities.","meaning":"exciting things to do that involve challenge and some risk","wrongMeanings":["quiet things to do that need no effort or skill","things to do that take place only in a classroom","things to do that cost nothing and last all day"]},{"contextId":"u5_35_adventurous_activities_paraphrase","text":"Insurance for adventurous activities costs more, because accidents are more likely when people climb, jump or race down rivers.","meaning":"sports and pastimes that are exciting and a little dangerous","wrongMeanings":["sports and pastimes that are calm and completely safe","games and lessons that are enjoyed mainly by young children","trips and visits that are arranged by a travel company"]}],"situationDistractors":["Guests sat quietly in the library and read magazines in comfortable armchairs.","The class painted watercolours of the village church while sitting on folding stools.","Retired visitors strolled slowly along the flat promenade and stopped for tea.","A museum curator explained the history of the clock to a small group.","The coach followed the main road through the valley and stopped at three villages.","They played cards in the lounge while the rain fell outside."],"gapDistractors":[{"contextId":"u5_35_adventurous_activities_gap_1","answer":"adventurous activities","wrong":["cooking lessons","language classes","quiet games"]},{"contextId":"u5_35_adventurous_activities_gap_2","answer":"adventurous activities","wrong":["reading groups","art lessons","music clubs"]},{"contextId":"u5_35_adventurous_activities_gap_3","answer":"adventurous activities","wrong":["cookery classes","painting sessions","story hours"]}],"spellingErrors":["adventurus activities","adventurous activites","advanturous activities","adventerous activities","adventurous activitys","adventurous actvities"],"masteryPassages":[{"passageId":"u5_35_adventurous_activities_passage_1","contextId":"u5_35_adventurous_activities_gap_1","text":"The valley has fast rivers, steep cliffs and tall pine forests. Visitors can try rafting, canyoning and climbing, and many say the ____ are the highlight of their holiday.","answer":"adventurous activities"},{"passageId":"u5_35_adventurous_activities_passage_2","contextId":"u5_35_adventurous_activities_gap_2","text":"Our school trip to the national park was not about museums or souvenirs. Every day we faced a new challenge, from crossing a rope bridge to paddling through rapids, and the instructors said that these ____ would build our confidence.","answer":"adventurous activities"}],"contextDependentParaphrases":[],"wrongParaphrases":["quiet things to do that need no effort","peaceful trips that follow the same route","gentle lessons that are given indoors"],"misleadingDistractors":["quiet pastimes that people do indoors in the evening","guided visits to museums and historic buildings","relaxing treatments such as massage and yoga"],"teacherNote":"The phrase names exciting things to do (plural noun phrase). It is not the adjective “adventurous” used for a person, which is taught earlier in the unit."}]'::jsonb,'[]'::jsonb,'["try adventurous activities","a range of adventurous activities","enjoy adventurous activities"]'::jsonb,'live'),
('vocab_memorable','memorable','adjective','special or unusual in a way that makes you remember it for a long time','[{"senseId":"memorable_1","meaning":"special or unusual in a way that makes you remember it for a long time","acceptedParaphrases":["worth remembering","easy to remember because it is special"],"masteryContexts":[{"contextId":"u5_36_memorable_meaning","text":"The cooking lesson with a local family was the most memorable part of our week in Thailand.","meaning":"so special that you remember it for a long time","wrongMeanings":["so cheap that you pay almost nothing for it","so crowded that you cannot enjoy it at all","so long that you become tired of it"]},{"contextId":"u5_36_memorable_paraphrase","text":"The guides made her birthday memorable by lighting a campfire and singing in three languages.","meaning":"special enough to be remembered for a long time","wrongMeanings":["boring enough to be forgotten within a few days","expensive enough to be paid for in advance","quiet enough to be enjoyed without any noise"]}],"situationDistractors":["The journey passed without anything unusual happening, and nobody could say afterwards what they had seen.","The meal was cold and plain, and the guests forgot it by the next morning.","Nothing special happened during the lecture, and most listeners left early.","The film was so dull that half the audience fell asleep before the end.","The room was clean but ordinary, with plain white walls and no view.","Most visitors walked past the small exhibit without stopping to read the sign."],"gapDistractors":[{"contextId":"u5_36_memorable_gap_1","answer":"memorable","wrong":["crowded","expensive","predictable"]},{"contextId":"u5_36_memorable_gap_2","answer":"memorable","wrong":["expensive","unnecessary","dangerous"]},{"contextId":"u5_36_memorable_gap_3","answer":"memorable","wrong":["tiring","dull","quiet"]}],"spellingErrors":["memorible","memerable","memorabel","memmorable","memarable","memorrable"],"masteryPassages":[{"passageId":"u5_36_memorable_passage_1","contextId":"u5_36_memorable_gap_1","text":"The ancient city is full of famous monuments, but visitors often say that the best moments were small ones. A conversation with a street musician or a meal in a family kitchen can make a trip truly ____, because years later you can still describe every detail.","answer":"memorable"},{"passageId":"u5_36_memorable_passage_2","contextId":"u5_36_memorable_gap_2","text":"Travel writers advise visitors to look for experiences that cannot be repeated. Watching a sunrise from a mountain top is ____ because you will keep the picture in your mind long after the photograph is lost.","answer":"memorable"}],"contextDependentParaphrases":[],"wrongParaphrases":["hard to understand","easy to forget","difficult to afford"],"misleadingDistractors":["likely to be forgotten quickly","too expensive for most people","difficult to find without a guide"]}]'::jsonb,'[]'::jsonb,'["memorable experience","memorable holiday","make it memorable"]'::jsonb,'live'),
('vocab_recommendation_5','recommendation','noun','a suggestion, based on experience, that a place, service or choice is good and worth choosing','[{"senseId":"recommendation_5_1","meaning":"a suggestion, based on experience, that a place, service or choice is good and worth choosing","acceptedParaphrases":["advice about what to choose","a suggestion about the best choice"],"masteryContexts":[{"contextId":"u5_37_recommendation_5_meaning","text":"Our host’s recommendation for a family-run café turned out to be the best meal of the trip.","meaning":"a suggestion from someone with experience that something is good and worth choosing","wrongMeanings":["a complaint from someone with experience that something is poor and not worth choosing","an order from someone with authority that something is required and must be chosen","a payment from someone with money that something is needed and must be bought"]},{"contextId":"u5_37_recommendation_5_paraphrase","text":"Online reviews are useful, but many travellers still prefer a personal recommendation from someone they know.","meaning":"advice from a person who says that something is worth choosing","wrongMeanings":["an advertisement from a company that says something is on sale","a warning from a guide who says that something is dangerous","a bill from a hotel that says something is unpaid"]}],"situationDistractors":["The receptionist asked guests to hand in their keys before they left the building.","The cyclist repaired a puncture at the side of the mountain road.","The museum closes at five on weekdays and at three on Sundays.","A thick fog covered the harbour and delayed the first ferry of the morning.","Two families shared a table in the crowded café and talked about football.","The pharmacist wrapped the sunscreen and put it into a paper bag."],"gapDistractors":[{"contextId":"u5_37_recommendation_5_gap_1","answer":"recommendation","wrong":["complaint","receipt","timetable"]},{"contextId":"u5_37_recommendation_5_gap_2","answer":"recommendation","wrong":["photograph","menu","delivery"]},{"contextId":"u5_37_recommendation_5_gap_3","answer":"recommendation","wrong":["punishment","payment","arrival"]}],"spellingErrors":["recomendation","reccomendation","recommendasion","recommedation","recommandation","recomendacion"],"wordFamilyForms":[{"form":"recommendation","partOfSpeech":"noun","example":"The mountain guide’s recommendation saved us from walking in bad weather.","pedagogicallyUseful":true},{"form":"recommend","partOfSpeech":"verb","example":"Most guidebooks recommend visiting the old harbour at sunrise.","pedagogicallyUseful":true,"altExample":"Local people recommend the fish soup at the harbour café."},{"form":"recommended","partOfSpeech":"adjective","example":"The tourist office has a leaflet of recommended walks for families.","pedagogicallyUseful":true,"altExample":"Book early if you want one of the recommended rooms on the top floor."}],"masteryPassages":[{"passageId":"u5_37_recommendation_5_passage_1","contextId":"u5_37_recommendation_5_gap_1","text":"We did not know which restaurant to try in the old town, so we asked the woman at the bakery. She sent us to a tiny family kitchen, and her ____ turned out to be perfect.","answer":"recommendation"},{"passageId":"u5_37_recommendation_5_passage_2","contextId":"u5_37_recommendation_5_gap_2","text":"The tourist office keeps a notebook of comments from earlier visitors. Staff read from it when families ask for a ____ about walks that are suitable for young children.","answer":"recommendation"}],"contextDependentParaphrases":[],"wrongParaphrases":["complaint about poor service","information about opening times","instructions for using a machine"],"misleadingDistractors":["a poster that persuades people to visit a place","a complaint about poor service at a restaurant","a list of prices for rooms and meals"],"teacherNote":"Unit 5 item (recommendation_5): advice from someone with experience that a place or service is worth choosing (not an advertisement). Unit 3 vocab_recommendation is a separate item that shares only the lexical spelling list."}]'::jsonb,'["recommend","recommended"]'::jsonb,'["personal recommendation","follow a recommendation","on the recommendation of"]'::jsonb,'live'),
('vocab_reservation','reservation','noun','an arrangement to have a room, a table or a seat kept for you until you arrive','[{"senseId":"reservation_1","meaning":"an arrangement to have a room, a table or a seat kept for you until you arrive","acceptedParaphrases":["advance booking","booking made before you arrive"],"masteryContexts":[{"contextId":"u5_38_reservation_meaning","text":"Without a reservation, you may not find a table at the lakeside restaurant on a Saturday night.","meaning":"an arrangement to have a table kept for you","wrongMeanings":["a request to change the menu for a large group","a payment made to a restaurant after a meal","a rule about the clothes that diners may wear"]},{"contextId":"u5_38_reservation_paraphrase","text":"The family cancelled their reservation two days before the festival because the baby was ill.","meaning":"a room or place that has been kept for someone in advance","wrongMeanings":["a room or place that has been cleaned for the next guest","a room or place that has been decorated for a special event","a room or place that has been left empty after an accident"]}],"situationDistractors":["The guide handed out maps and pointed to the best viewing platform.","The shop assistant gave the customer a receipt, and the customer put it in a pocket.","Walkers rested on the hillside and ate sandwiches in the sunshine.","The singer waved to the crowd and the band began their second song.","It took nearly an hour to push the broken-down coach to the side of the road.","The local newspaper published photographs of the winning team."],"gapDistractors":[{"contextId":"u5_38_reservation_gap_1","answer":"reservation","wrong":["complaint","donation","suggestion"]},{"contextId":"u5_38_reservation_gap_2","answer":"reservation","wrong":["tent","map","torch"]},{"contextId":"u5_38_reservation_gap_3","answer":"reservation","wrong":["umbrella","jacket","menu"]}],"spellingErrors":["resevation","reservaton","reservashun","resirvation","reservatoin","reservasion"],"wordFamilyForms":[{"form":"reservation","partOfSpeech":"noun","example":"The hostel will hold your reservation until six o’clock on the day of arrival.","pedagogicallyUseful":true},{"form":"reserve","partOfSpeech":"verb","example":"You can reserve a seat on the night coach by telephoning the office.","pedagogicallyUseful":true,"altExample":"Visitors should reserve their places on the glacier walk at least a week ahead."},{"form":"reserved","partOfSpeech":"adjective","example":"A reserved seat means that nobody else can sit in it.","pedagogicallyUseful":true,"altExample":"Please do not park in the reserved spaces outside the information centre."}],"masteryPassages":[{"passageId":"u5_38_reservation_passage_1","contextId":"u5_38_reservation_gap_1","text":"The ski season begins in December, and the best chalets are full by October. Families who want a room near the slopes are advised to make a ____ as early as possible.","answer":"reservation"},{"passageId":"u5_38_reservation_passage_2","contextId":"u5_38_reservation_gap_2","text":"We turned up at the restaurant without telling anyone and asked for a table for eight. The waiter smiled politely and explained that every table had a ____ for the evening.","answer":"reservation"}],"contextDependentParaphrases":[],"wrongParaphrases":["final payment","spare ticket","late arrival"],"misleadingDistractors":["a message that confirms that a payment has been received","a list of the rooms that are still empty","a card that opens the door of a room"],"teacherNote":"Tourism/booking sense only: a place, room or table kept for you in advance. Not the “doubt” sense or a nature reserve."}]'::jsonb,'["reserve","reserved"]'::jsonb,'["make a reservation","cancel a reservation","a table reservation"]'::jsonb,'live'),
('vocab_destination_5','destination','noun','a place that people travel to for a holiday, a visit or a particular activity','[{"senseId":"destination_5_1","meaning":"a place that people travel to for a holiday, a visit or a particular activity","acceptedParaphrases":["holiday spot","place you are travelling to"],"masteryContexts":[{"contextId":"u5_39_destination_5_meaning","text":"The ferry slowed as it approached the island, and the passengers gathered at the rail to see their destination at last.","meaning":"the place that someone is travelling to","wrongMeanings":["the road that someone is travelling along","the time that someone is spending on a trip","the people that someone is travelling with"]},{"contextId":"u5_39_destination_5_paraphrase","text":"Patagonia is a dream destination for walkers who want empty trails and enormous mountains.","meaning":"a place that people choose to visit for a holiday","wrongMeanings":["a plan that people make for a holiday","a company that people pay for a holiday","a price that people agree for a holiday"]}],"situationDistractors":["The driver stopped for petrol and checked the oil before continuing down the motorway.","The conductor announced that the train would be forty minutes late because of a signal failure.","Rain drummed on the tent all night, and nobody slept well.","The photographer waited an hour for the light to change over the lake.","A group of schoolchildren sang as the coach climbed the winding road.","The ticket machine was out of order, so passengers queued at the office window."],"gapDistractors":[{"contextId":"u5_39_destination_5_gap_1","answer":"destination","wrong":["budget","insurance","timetable"]},{"contextId":"u5_39_destination_5_gap_2","answer":"destination","wrong":["payment","speed","repair"]},{"contextId":"u5_39_destination_5_gap_3","answer":"destination","wrong":["umbrella","sandwich","calendar"]}],"spellingErrors":["destinashun","destenation","destinasion","destanation","destinaton","distination"],"masteryPassages":[{"passageId":"u5_39_destination_5_passage_1","contextId":"u5_39_destination_5_gap_1","text":"Many airlines now show passengers the weather and a short film about the city they are about to visit. The pilot announced that we would land in ten minutes, and everyone looked out of the window to catch the first glimpse of our ____.","answer":"destination"},{"passageId":"u5_39_destination_5_passage_2","contextId":"u5_39_destination_5_gap_2","text":"The island has no motorways, no factories and only one small village. The brochure describes it as an ideal ____ for walkers, bird-watchers and anyone who wants to escape city life.","answer":"destination"}],"contextDependentParaphrases":[],"wrongParaphrases":["train timetable","travel document","luggage label"],"misleadingDistractors":["the long trip that leads to a place","the company that arranges a holiday","the date on which a holiday begins"],"teacherNote":"Unit 5 item (destination_5): a place that people travel to for a holiday or a visit. Unit 4 vocab_destination is a separate item that shares only the lexical spelling list."}]'::jsonb,'[]'::jsonb,'["holiday destination","final destination","tourist destination"]'::jsonb,'live'),
('vocab_availability_5','availability','noun','whether rooms, tickets or places are free and can be booked','[{"senseId":"availability_5_1","meaning":"whether rooms, tickets or places are free and can be booked","acceptedParaphrases":["whether rooms are free to book","how many seats or rooms are still free"],"masteryContexts":[{"contextId":"u5_40_availability_5_meaning","text":"Tickets for the boat trip are limited, so online availability changes every hour in summer.","meaning":"whether there are places or seats still free to book","wrongMeanings":["how many people want to travel in a particular season","how much money is needed to pay for a place","how far a place is from the main road"]},{"contextId":"u5_40_availability_5_paraphrase","text":"The agent told us that availability was poor in August, because almost every campsite in the region was already full.","meaning":"how easy it is to find a free place that can be booked","wrongMeanings":["how popular a region is with visitors from abroad","how much a booking costs in the busiest month","how well a region is known to local people"]}],"situationDistractors":["A volunteer collected the litter from the path and put it in large sacks.","The jazz club puts a small band on the stage every Thursday night.","The caretaker locked the gates at dusk and checked the windows.","The old tram climbs the steep hill and stops outside the museum.","Her passport photograph made her laugh because her hair looked so strange.","Fresh snow had covered the car park by the time the skiers finished their lunch."],"gapDistractors":[{"contextId":"u5_40_availability_5_gap_1","answer":"availability","wrong":["comfort","price","design"]},{"contextId":"u5_40_availability_5_gap_2","answer":"availability","wrong":["cleaning","temperature","decoration"]},{"contextId":"u5_40_availability_5_gap_3","answer":"availability","wrong":["advertising","weather","payment"]}],"spellingErrors":["availablity","avalibility","availabilty","aviability","availibility","availabilaty"],"wordFamilyForms":[{"form":"availability","partOfSpeech":"noun","example":"Please ring the agency to ask about availability for the August holiday week.","pedagogicallyUseful":true},{"form":"available","partOfSpeech":"adjective","example":"Only two double rooms are still available for the night of the festival.","pedagogicallyUseful":true,"altExample":"Is a table for four available on Saturday evening?"},{"form":"unavailable","partOfSpeech":"adjective","example":"The cabin is unavailable in August because the owners use it themselves.","pedagogicallyUseful":true,"altExample":"Most morning trips were unavailable because the boat was being repaired."}],"masteryPassages":[{"passageId":"u5_40_availability_5_passage_1","contextId":"u5_40_availability_5_gap_1","text":"We wanted to visit Rome in the middle of August, but every site we tried showed a red message saying that there was no ____ for our dates. In the end we moved the trip to September, when plenty of rooms were free.","answer":"availability"},{"passageId":"u5_40_availability_5_passage_2","contextId":"u5_40_availability_5_gap_2","text":"Before booking, the agent opened her computer and checked ____ for the week of the music festival. Only two rooms remained, and she suggested that we decide quickly.","answer":"availability"}],"contextDependentParaphrases":[],"wrongParaphrases":["how popular rooms are with guests","how much rooms cost in winter","how large rooms are for families"],"misleadingDistractors":["the number of people who want to go to a place","the price of rooms during the busiest weeks","the distance from a campsite to the nearest village"],"teacherNote":"Unit 5 item (availability_5): whether rooms, tickets or places are free and can be booked. Unit 2 vocab_availability is a separate item that shares only the lexical spelling list."}]'::jsonb,'["available","unavailable"]'::jsonb,'["room availability","check availability","limited availability"]'::jsonb,'live')
