values
('u5_31_tourism_industry_meaning','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','meaning_context','The tourism industry employs one in ten workers in the country, from cleaners to pilots.',null,'["businesses that serve holidaymakers"]'::jsonb,null,'live'),
('u5_31_tourism_industry_paraphrase','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','paraphrase_context','The businesses that serve holidaymakers employ one in ten workers in the country, from cleaners to pilots.','businesses that serve holidaymakers','["tourism industry"]'::jsonb,null,'live'),
('u5_31_tourism_industry_production','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','production_context','Many students hope to build a career in the business of looking after holidaymakers, perhaps as a tour guide.','the business of looking after holidaymakers','["tourism industry"]'::jsonb,null,'live'),
('u5_31_tourism_industry_gap_1','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','gap_fill','Airlines, restaurants, coach firms and tour companies all belong to the tourism industry, which provides millions of jobs worldwide.','tourism industry','["tourism industry"]'::jsonb,null,'live'),
('u5_31_tourism_industry_gap_2','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','gap_fill','When the borders closed, the tourism industry lost almost all of its customers, and thousands of guides and drivers lost their jobs.','tourism industry','["tourism industry"]'::jsonb,null,'live'),
('u5_31_tourism_industry_gap_3','vocab_tourism_industry','u5_31_tourism_industry','tourism_industry_1','gap_fill','A degree in hospitality management can lead to a career in the tourism industry, perhaps as a hotel manager or a travel agent.','tourism industry','["tourism industry"]'::jsonb,null,'live'),
('u5_32_exploring_meaning','vocab_exploring','u5_32_exploring','exploring_1','meaning_context','For me, exploring is the best part of a holiday, because I love finding streets that are not in the guidebooks.',null,'["discovering new places"]'::jsonb,null,'live'),
('u5_32_exploring_paraphrase','vocab_exploring','u5_32_exploring','exploring_1','paraphrase_context','For me, discovering new places is the best part of a holiday, because I love finding streets that are not in the guidebooks.','discovering new places','["exploring"]'::jsonb,null,'live'),
('u5_32_exploring_production','vocab_exploring','u5_32_exploring','exploring_1','production_context','Part of the school trip is spent finding out about a place by travelling around it.','finding out about a place by travelling around it','["exploring"]'::jsonb,null,'live'),
('u5_32_exploring_gap_1','vocab_exploring','u5_32_exploring','exploring_1','gap_fill','The best way to enjoy the old city is by exploring its narrow streets on foot, without a map.','exploring','["exploring"]'::jsonb,null,'live'),
('u5_32_exploring_gap_2','vocab_exploring','u5_32_exploring','exploring_1','gap_fill','Children on the nature course spend their mornings exploring the forest and writing down what they find.','exploring','["exploring"]'::jsonb,null,'live'),
('u5_32_exploring_gap_3','vocab_exploring','u5_32_exploring','exploring_1','gap_fill','After a week of exploring the islands by boat, the travellers knew every bay and village.','exploring','["exploring"]'::jsonb,null,'live'),
('u5_33_observation_meaning','vocab_observation','u5_33_observation','observation_1','meaning_context','Several weeks of observation showed that the birds return to the same nests every spring.',null,'["careful watching"]'::jsonb,null,'live'),
('u5_33_observation_paraphrase','vocab_observation','u5_33_observation','observation_1','paraphrase_context','Several weeks of careful watching showed that the birds return to the same nests every spring.','careful watching','["observation"]'::jsonb,null,'live'),
('u5_33_observation_production','vocab_observation','u5_33_observation','observation_1','production_context','The expedition’s findings are based on close and patient watching of the glacier over three winters.','close and patient watching','["observation"]'::jsonb,null,'live'),
('u5_33_observation_gap_1','vocab_observation','u5_33_observation','observation_1','gap_fill','The researchers did not touch the nests; their findings were based entirely on observation from a hide.','observation','["observation"]'::jsonb,null,'live'),
('u5_33_observation_gap_2','vocab_observation','u5_33_observation','observation_1','gap_fill','Good guides know that careful observation of the weather is part of keeping visitors safe in the mountains.','observation','["observation"]'::jsonb,null,'live'),
('u5_33_observation_gap_3','vocab_observation','u5_33_observation','observation_1','gap_fill','During a nature trip, a notebook and binoculars are the most useful tools for observation.','observation','["observation"]'::jsonb,null,'live'),
('u5_34_relaxation_meaning','vocab_relaxation','u5_34_relaxation','relaxation_1','meaning_context','Many people book a week at a quiet lakeside cabin in search of relaxation after a busy year at work.',null,'["rest and freedom from stress"]'::jsonb,null,'live'),
('u5_34_relaxation_paraphrase','vocab_relaxation','u5_34_relaxation','relaxation_1','paraphrase_context','Many people book a week at a quiet lakeside cabin in search of rest and freedom from stress after a busy year at work.','rest and freedom from stress','["relaxation"]'::jsonb,null,'live'),
('u5_34_relaxation_production','vocab_relaxation','u5_34_relaxation','relaxation_1','production_context','The spa garden gives guests an hour of calm time without worry after a hard week.','calm time without worry','["relaxation"]'::jsonb,null,'live'),
('u5_34_relaxation_gap_1','vocab_relaxation','u5_34_relaxation','relaxation_1','gap_fill','Teachers who need a break from their students often choose a holiday of relaxation, with no timetable and no alarm clock.','relaxation','["relaxation"]'::jsonb,null,'live'),
('u5_34_relaxation_gap_2','vocab_relaxation','u5_34_relaxation','relaxation_1','gap_fill','The riverside garden has hammocks, soft music and shady trees, so it is a perfect place for relaxation.','relaxation','["relaxation"]'::jsonb,null,'live'),
('u5_34_relaxation_gap_3','vocab_relaxation','u5_34_relaxation','relaxation_1','gap_fill','Doctors say that regular relaxation is as important for health as good food and enough sleep.','relaxation','["relaxation"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_meaning','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','meaning_context','The mountain resort is best known for its adventurous activities, including rock climbing, rafting and zip-lining.',null,'["exciting things to do that involve some risk"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_paraphrase','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','paraphrase_context','The mountain resort is best known for its exciting things to do that involve some risk, including rock climbing, rafting and zip-lining.','exciting things to do that involve some risk','["adventurous activities"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_production','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','production_context','The youth camp specialises in thrilling outdoor pursuits such as canoeing and abseiling.','thrilling outdoor pursuits','["adventurous activities"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_gap_1','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','gap_fill','The holiday camp organises adventurous activities such as rock climbing, canoeing and zip-lining for teenagers.','adventurous activities','["adventurous activities"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_gap_2','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','gap_fill','Parents should check the safety rules before their children join adventurous activities like white-water rafting.','adventurous activities','["adventurous activities"]'::jsonb,null,'live'),
('u5_35_adventurous_activities_gap_3','vocab_adventurous_activities','u5_35_adventurous_activities','adventurous_activities_1','gap_fill','Because of the danger, you must be over sixteen to take part in the adventurous activities at the outdoor centre.','adventurous activities','["adventurous activities"]'::jsonb,null,'live'),
('u5_36_memorable_meaning','vocab_memorable','u5_36_memorable','memorable_1','meaning_context','Our trip to the volcano was memorable, so we still talk about it every year.',null,'["worth remembering"]'::jsonb,null,'live'),
('u5_36_memorable_paraphrase','vocab_memorable','u5_36_memorable','memorable_1','paraphrase_context','Our trip to the volcano was worth remembering, so we still talk about it every year.','worth remembering','["memorable"]'::jsonb,null,'live'),
('u5_36_memorable_production','vocab_memorable','u5_36_memorable','memorable_1','production_context','Anything that is easy to remember because it is special deserves a place in your holiday diary.','easy to remember because it is special','["memorable"]'::jsonb,null,'live'),
('u5_36_memorable_gap_1','vocab_memorable','u5_36_memorable','memorable_1','gap_fill','Sleeping in a snow hole under the stars was the most memorable night of my life.','memorable','["memorable"]'::jsonb,null,'live'),
('u5_36_memorable_gap_2','vocab_memorable','u5_36_memorable','memorable_1','gap_fill','The guide told such a funny story about the castle that the visit became memorable for every child in the group.','memorable','["memorable"]'::jsonb,null,'live'),
('u5_36_memorable_gap_3','vocab_memorable','u5_36_memorable','memorable_1','gap_fill','Their wedding photographs show a memorable day, full of laughter, music and old friends.','memorable','["memorable"]'::jsonb,null,'live'),
('u5_37_recommendation_5_meaning','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','meaning_context','Before booking the cruise, read the reviews and ask your friends for a recommendation.',null,'["advice about what to choose"]'::jsonb,null,'live'),
('u5_37_recommendation_5_paraphrase','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','paraphrase_context','Before booking the cruise, read the reviews and ask your friends for advice about what to choose.','advice about what to choose','["recommendation"]'::jsonb,null,'live'),
('u5_37_recommendation_5_production','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','production_context','The woman at the information desk gave us a suggestion about the best choice for a rainy day.','a suggestion about the best choice','["recommendation"]'::jsonb,null,'live'),
('u5_37_recommendation_5_gap_1','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','gap_fill','If you are visiting Kyoto for the first time, ask the owner of your guesthouse for a recommendation about the best temples to see.','recommendation','["recommendation"]'::jsonb,null,'live'),
('u5_37_recommendation_5_gap_2','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','gap_fill','The restaurant was almost empty until a well-known critic wrote a positive recommendation of its seafood, and then every table was booked.','recommendation','["recommendation"]'::jsonb,null,'live'),
('u5_37_recommendation_5_gap_3','vocab_recommendation_5','u5_37_recommendation_5','recommendation_5_1','gap_fill','Many travellers trust the recommendation of a friend more than any advertisement in a magazine.','recommendation','["recommendation"]'::jsonb,null,'live'),
('u5_38_reservation_meaning','vocab_reservation','u5_38_reservation','reservation_1','meaning_context','I made a reservation for a table for six at the mountain restaurant.',null,'["advance booking"]'::jsonb,null,'live'),
('u5_38_reservation_paraphrase','vocab_reservation','u5_38_reservation','reservation_1','paraphrase_context','I made an advance booking for a table for six at the mountain restaurant.','advance booking','["reservation"]'::jsonb,null,'live'),
('u5_38_reservation_production','vocab_reservation','u5_38_reservation','reservation_1','production_context','A booking made before you arrive guarantees a bed on the busiest weekends.','booking made before you arrive','["reservation"]'::jsonb,null,'live'),
