('u5_38_reservation_gap_2','vocab_reservation','u5_38_reservation','reservation_1','gap_fill','I rang the campsite to change the dates on my reservation, but the manager said that the weekend was already full.','reservation','["reservation"]'::jsonb,null,'live'),
('u5_38_reservation_gap_3','vocab_reservation','u5_38_reservation','reservation_1','gap_fill','You can keep your reservation until six o’clock; after that, the restaurant gives the table to other customers.','reservation','["reservation"]'::jsonb,null,'live'),
('u5_39_destination_5_meaning','vocab_destination_5','u5_39_destination_5','destination_5_1','meaning_context','Many travel writers rank Costa Rica as the top destination for anyone who loves rainforests.',null,'["holiday spot"]'::jsonb,null,'live'),
('u5_39_destination_5_paraphrase','vocab_destination_5','u5_39_destination_5','destination_5_1','paraphrase_context','Many travel writers rank Costa Rica as the top holiday spot for anyone who loves rainforests.','holiday spot','["destination"]'::jsonb,null,'live'),
('u5_39_destination_5_production','vocab_destination_5','u5_39_destination_5','destination_5_1','production_context','Always check the weather in the place you are travelling to before you pack.','place you are travelling to','["destination"]'::jsonb,null,'live'),
