('u5_39_destination_5_gap_2','vocab_destination_5','u5_39_destination_5','destination_5_1','gap_fill','The tour guide asked the passengers to stay in their seats until the bus had reached its final destination.','destination','["destination"]'::jsonb,null,'live'),
('u5_39_destination_5_gap_3','vocab_destination_5','u5_39_destination_5','destination_5_1','gap_fill','Safety is the first thing many parents consider when choosing a family destination.','destination','["destination"]'::jsonb,null,'live'),
('u5_40_availability_5_meaning','vocab_availability_5','u5_40_availability_5','availability_5_1','meaning_context','The booking website shows the availability of rooms for the next six months.',null,'["whether rooms are free to book"]'::jsonb,null,'live'),
